  // The menu elements live outside of the table.
  const treeView = this.closest(".tree-view-scrollable-container");
  treeView.appendChild(this.#pickerContext);

  this.addEventListener("contextmenu", event => {
    event.stopPropagation();
    event.preventDefault();
    const table = this.closest("table");
    if (table.editable) {
      this.#pickerContext.openPopup(event.target, { triggerEvent: event });
    }
  });
  this.addEventListener("click", event => {
    const button = event.target.closest(".button-column-picker");
    if (button) {
      event.stopPropagation();
      event.preventDefault();
      const table = this.closest("table");
      if (table.editable) {
        this.#pickerContext.openPopup(button, {
          position: "after_end",
          triggerEvent: event,
        });
      }
    }
  });
}

disconnectedCallback() {
  this.#resizeObserver.disconnect();
}

handleEvent(event) {
  switch (event.type) {
    case "keypress":
      this.#onKeyPress(event);
      break;
    case "dragstart":
      this.#onDragStart(event);
      break;
    case "dragover":
      this.#onDragOver(event);
      break;
    case "dragend":
      this.#onDragEnd();
      break;
    case "drop":
      this.#onDrop(event);
      break;
  }
}

#onKeyPress(event) {
  if (!event.altKey || !["ArrowRight", "ArrowLeft"].includes(event.key)) {
    this.triggerTableHeaderRovingTab(event);
    return;
  }

  const column = event.target.closest(`th[is="tree-view-table-header-cell"]`);
  if (!column) {
    return;
  }

  const visibleColumns = this.parentNode.columns.filter(c => !c.hidden);
  const forward =
    event.key == (document.dir === "rtl" ? "ArrowLeft" : "ArrowRight");

  // Bail out if the user is trying to shift backward the first column, or
  // shift forward the last column.
  if (
    (!forward && visibleColumns.at(0)?.id == column.id) ||
    (forward && visibleColumns.at(-1)?.id == column.id)
  ) {
    return;
  }

  event.preventDefault();
  event.stopPropagation();
  this.dispatchEvent(
    new CustomEvent("shift-column", {
      bubbles: true,
      detail: {
        column: column.id,
        forward,
      },
    })
  );
}
